package com.pokedaisy.app.companion.data

/**
 * 宝可梦水银 v1.33's own Johto / Kanto region map: its sections, their Chinese names and the 50x36 tile
 * grids, recovered from the community 1.6.1 Chinese build by 问风 (closed source, APK only). The two map
 * pictures are bundled at assets/regionmap/mercury_j1.png and mercury_j2.png from that build; the ROM's own
 * map layout isn't readable by RomRegionMap when this hack repurposes its region-map pointer.
 */
private const val MERCURY_SECTIONS = "99:擂钵山:26:12:2:2:0;127:呆呆兽之井:24:28:2:4:0;130:50号水路:28:26:6:8:0;134:阿露福遗迹:24:18:2:4:0;135:铃铛塔:22:10:4:2:0;140:喇叭芽之塔:28:16:2:2:0;143:若叶镇:40:26:2:2:0;144:吉野市:30:26:4:2:0;145:桔梗市:26:16:4:4:0;146:桧皮镇:22:30:2:2:0;147:满金市:16:22:6:4:0;148:缘朱市:20:12:4:2:0;149:浅葱市:14:16:4:4:0;150:湛蓝市:8:24:2:2:0;151:卡吉镇:30:12:2:2:0;152:烟墨市:38:10:4:4:0;154:29号道路:34:26:6:2:0;155:30号道路:32:20:2:6:0;156:31号道路:30:18:2:2:0;157:32号道路:26:20:2:8:0;158:33号道路:26:30:2:2:0;159:34号道路:20:26:2:4:0;160:35号道路:20:18:2:4:0;161:36号道路:22:16:4:2:0;162:37号道路:22:14:2:2:0;163:38号道路:16:12:4:2:0;164:39号道路:14:12:2:4:0;165:40号水路:12:18:2:4:0;166:41号水路:10:22:4:4:0;167:42号道路:24:12:6:2:0;168:43号道路:30:8:2:4:0;169:44号道路:32:12:6:2:0;170:45号道路:38:16:2:6:0;171:46号道路:36:22:2:4:0;176:漩涡岛:12:24:2:2:0;177:黑暗洞穴:32:14:6:10:0;178:自然公园:18:14:4:4:0;180:连接洞:26:28:2:2:0;181:冰天地:40:10:2:2:0;182:桐树林:20:30:2:4:0;183:烧焦塔:20:10:2:2:0;186:光辉灯塔:16:18:2:2:0;187:愤怒之湖:28:4:6:4:0;195:51号水路:28:32:2:2:0;199:48号道路:2:22:4:2:0;200:47号道路:2:24:6:4:0;201:断崖镇:2:18:4:4:0;202:27号道路:42:26:8:2:0;207:破海洞穴:8:22:2:2:0;208:海之彼岸:8:18:2:2:0;209:不知名遗迹:10:14:4:4:0;210:都城瀑布:44:26:2:2:0;211:埋藏之塔:2:18:2:2:0;212:寂静之丘:30:32:2:2:0;214:城都矿山:14:26:2:2:0;97:石英高原:5:14:2:2:1;123:23号公路:5:20:2:3:1;132:冠军之路:5:16:2:4:1;203:26号道路:5:23:2:5:1"

private const val MERCURY_JOHTO_GRID = ""

private const val MERCURY_KANTO_GRID = ""

val mercuryMapImages = arrayOf("mercury_j1", "mercury_j2")

/** Mercury's map sections by mapsec id: name, region (0 Johto, 1 Kanto), then the rect in 8px tiles. */
val mercSecData: Map<Int, MapSecInfo> by lazy {
    buildMap {
        for (row in MERCURY_SECTIONS.split(';')) {
            if (row.isBlank()) continue
            val p = row.split(':')
            put(p[0].toInt(), MapSecInfo(p[1], p[6].toInt(), p[2].toInt(), p[3].toInt(), p[4].toInt(), p[5].toInt()))
        }
    }
}

/** The two maps' own cursor grids (the same mapsec bytes twice: sections and dungeons). */
val mercuryRegionLayouts: List<RegionLayout> by lazy {
    listOf(
        RegionLayout(0, 0, 50, 36, 0, listOf(hexBytes(MERCURY_JOHTO_GRID), hexBytes(MERCURY_JOHTO_GRID)), 1),
        RegionLayout(0, 0, 50, 36, 0, listOf(hexBytes(MERCURY_KANTO_GRID), hexBytes(MERCURY_KANTO_GRID)), 1),
    )
}

fun mercModel(): RegionMapModel = RegionMapModel(mercuryMapImages, mercSecData, mercuryRegionLayouts)
